            if ((self.tag == .WTFStringImpl)) {
                return self.value.WTFStringImpl.hasPrefix(value);
            }
            var str = self.toZigString();
            _ = &str;
            if ((str.len < value.len)) {
                return false;
            }
            return str.substringWithLen(0, value.len).eqlComptime(value);
    }

pub fn isWTFAllocator(alloc: std.mem.Allocator) bool {
            return (alloc.vtable == wtf.StringImplAllocator.VTablePtr);
    }

pub fn eqlBytes(self: String, value: []const u8) bool {
            return bun.strings.eqlLong(self.byteSlice(), value, true);
    }

pub fn toThreadSafe(self: *String) void {
            _ = jsc.markBinding(@src());
            if ((self.tag == .WTFStringImpl)) {
                _ = bun.cpp.BunString__toThreadSafe(self);
            }
    }

pub fn toThreadSafeEnsureRef(self: *String) void {
            _ = jsc.markBinding(@src());
            if ((self.tag == .WTFStringImpl)) {
                _ = bun.cpp.BunString__toThreadSafe(self);
                _ = self.value.WTFStringImpl.ref();
            }
    }

pub fn eqlUTF8(self: String, other: []const u8) bool {
            return self.toZigString().eql(ZigString.fromUTF8(other));
    }

pub fn eql(self: String, other: String) bool {
            return self.toZigString().eql(other.toZigString());
    }

pub fn estimatedSize(self: *const String) usize {
            return (switch (self.tag) {
.Dead, .Empty, .StaticZigString => 0,
.ZigString => self.value.ZigString.len,
.WTFStringImpl => self.value.WTFStringImpl.byteLength(),
});
    }
