pub const SliceWithUnderlyingString = struct {
    utf8: ZigString.Slice = ZigString.Slice.empty,
    underlying: String = String.dead,
    did_report_extra_memory_debug: bun.DebugOnly(bool) = (if (bun.Environment.isDebug) false else ({
})),

pub inline fn reportExtraMemory(self: *SliceWithUnderlyingString, vm: *jsc.VM) void {
            if (comptime bun.Environment.isDebug) {
                _ = bun.assert((!self.did_report_extra_memory_debug));
                self.did_report_extra_memory_debug = (if (comptime @typeInfo(bun.DebugOnly(bool)) == .@"enum") @as(bun.DebugOnly(bool), @enumFromInt(true)) else @as(bun.DebugOnly(bool), true));
            }
            _ = self.utf8.reportExtraMemory(vm);
    }

pub fn isWTFAllocated(self: *const SliceWithUnderlyingString) bool {
            if (self.utf8.allocator.get()) |allocator| {
                _ = &allocator;
                const is_wtf_allocator = String.isWTFAllocator(allocator);
                return is_wtf_allocator;
            }
            return false;
    }

pub fn dupeRef(self: SliceWithUnderlyingString) SliceWithUnderlyingString {
            return .{ .utf8 = ZigString.Slice.empty, .underlying = self.underlying.dupeRef() };
    }

pub fn transcodeFromOwnedSlice(owned_input_bytes: []u8, encoding: jsc.Node.Encoding) SliceWithUnderlyingString {
            if ((owned_input_bytes.len == 0)) {
                return .{ .utf8 = ZigString.Slice.empty, .underlying = String.empty };
            }
            return .{ .underlying = jsc.WebCore.encoding.toBunStringFromOwnedSlice(owned_input_bytes, encoding) };
    }

pub fn fromUTF8(utf8: []const u8) SliceWithUnderlyingString {
            return .{ .utf8 = ZigString.Slice.init(bun.default_allocator, utf8), .underlying = String.dead };
    }

pub fn toThreadSafe(self: *SliceWithUnderlyingString) void {
            if ((self.underlying.tag == .WTFStringImpl)) {
                const orig = self.underlying.value.WTFStringImpl;
                _ = self.underlying.toThreadSafe();
                if ((self.underlying.value.WTFStringImpl != orig)) {
                    if (self.utf8.allocator.get()) |allocator| {
                        _ = &allocator;
                        if (String.isWTFAllocator(allocator)) {
                            _ = self.utf8.deinit();
                            self.utf8 = self.underlying.value.WTFStringImpl.toLatin1Slice();
                        }
                    }
                }
            }
    }

pub fn deinit(self: SliceWithUnderlyingString) void {
            _ = self.utf8.deinit();
            _ = self.underlying.deref();
    }

pub fn slice(self: *const SliceWithUnderlyingString) []const u8 {
            return self.utf8.slice();
    }

pub fn format(self: SliceWithUnderlyingString, writer: *std.Io.Writer) !void {
            if ((self.utf8.len == 0)) {
                _ = try self.underlying.format(writer);
                return;
            }
            _ = try writer.writeAll(self.utf8.slice());
    }
    pub const toJS = string_jsc.sliceWithUnderlyingStringToJS;
    pub const transferToJS = string_jsc.sliceWithUnderlyingStringTransferToJS;
};

